// YammmGrammarLexerInit initializes any static state used to implement YammmGrammarLexer. By default the
// static state used to implement the lexer is lazily initialized during the first call to
// NewYammmGrammarLexer(). You can call this function if you wish to initialize the static state ahead
// of time.
func YammmGrammarLexerInit() {
	staticData := &YammmGrammarLexerLexerStaticData
	staticData.once.Do(yammmgrammarlexerLexerInit)
}

// NewYammmGrammarLexer produces a new lexer instance for the optional input antlr.CharStream.
func NewYammmGrammarLexer(input antlr.CharStream) *YammmGrammarLexer {
	YammmGrammarLexerInit()
	l := new(YammmGrammarLexer)
	l.BaseLexer = antlr.NewBaseLexer(input)
	staticData := &YammmGrammarLexerLexerStaticData
	l.Interpreter = antlr.NewLexerATNSimulator(l, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	l.channelNames = staticData.ChannelNames
	l.modeNames = staticData.ModeNames
	l.RuleNames = staticData.RuleNames
	l.LiteralNames = staticData.LiteralNames
	l.SymbolicNames = staticData.SymbolicNames
	l.GrammarFileName = "YammmGrammar.g4"
	// TODO: l.EOF = antlr.TokenEOF

	return l
}

